def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    result = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for _ in range(n):
            matrix.append(list(lines[idx]))
            idx += 1

        count = 0

        # Type 1: Axis-aligned squares
        for r1 in range(n):
            for c1 in range(m):
                for k in range(1, min(n - r1, m - c1)):
                    r2 = r1 + k
                    c2 = c1 + k

                    # Check if all border cells are '1'
                    top_border = all(matrix[r1][c] == '1' for c in range(c1, c2 + 1))
                    bottom_border = all(matrix[r2][c] == '1' for c in range(c1, c2 + 1))
                    left_border = all(matrix[r][c1] == '1' for r in range(r1 + 1, r2))
                    right_border = all(matrix[r][c2] == '1' for r in range(r1 + 1, r2 + 1))

                    if not (top_border and bottom_border and left_border and right_border):
                        continue

                    # Check no foreign 1s touch the border (adjacent cells must be '0')
                    is_valid = True
                    for r in range(r1 - 1, r2 + 2):
                        for c in range(c1 - 1, c2 + 2):
                            if r < 0 or r >= n or c < 0 or c >= m:
                                continue
                            if not (r1 <= r <= r2 and c1 <= c <= c2):
                                if matrix[r][c] == '1':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break

                    if is_valid:
                        count += 1

        # Type 2: Diagonal (X-shaped) squares
        for r1 in range(n):
            for c1 in range(m):
                for k in range(1, min(n - r1, m - c1)):
                    r2 = r1 + k
                    c2 = c1 + k

                    # For diagonal square, check X pattern on border
                    is_x_valid = True
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            on_main_diag = (r - r1) == (c - c1)
                            on_sec_diag = (r - r1) == (c2 - c)
                            if on_main_diag or on_sec_diag:
                                if matrix[r][c] != '1':
                                    is_x_valid = False
                                    break
                        if not is_x_valid:
                            break

                    if not is_x_valid:
                        continue

                    # Check no foreign 1s touch the X
                    is_valid = True
                    for r in range(r1 - 1, r2 + 2):
                        for c in range(c1 - 1, c2 + 2):
                            if r < 0 or r >= n or c < 0 or c >= m:
                                continue
                            if r1 <= r <= r2 and c1 <= c <= c2:
                                on_main_diag = (r - r1) == (c - c1)
                                on_sec_diag = (r - r1) == (c2 - c)
                                if not on_main_diag and not on_sec_diag:
                                    if matrix[r][c] == '1':
                                        is_valid = False
                                        break
                            else:
                                if matrix[r][c] == '1':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break

                    if is_valid:
                        count += 1

        result.append(str(count))

    return '\n'.join(result)
