    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * finv[r] % MOD * finv[n-r] % MOD

    answers_cache = {}
    for n in range(1, MAX_N):
        temp = n
        counts = []
        while temp > 1:
            p = spf[temp]
