                temp //= p
            counts.append(cnt)

        if not counts:
            for r in range(T_MAX):
                answers_cache[(r, n)] = 1
            continue

        for r in range(T_MAX):
            result = 1
            for cnt in counts:
                result = (result * nCr_mod(cnt + r - 1, r)) % MOD
            answers_cache[(r, n)] = result

def solution(input_str):
    # Global precomputation
