```python
from functools import lru_cache

def solution(input_string):
    n, k, m = map(int, input_string.split())
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def dp(current, visited):
        if len(visited) == k:
            return 1

        total = 0
        # From current position, can jump to [1, current + m]
        for nxt in range(1, min(n, current + m) + 1):
            if nxt not in visited:
                new_visited = visited | {nxt}
                # Check if we have enough remaining unvisited planets to complete the path
                if n - len(new_visited) >= k - len(new_visited) - 1:
                    total = (total + dp(nxt, new_visited)) % MOD

        return total

    ans = 0
    for start in range(1, n + 1):
        ans = (ans + dp(start, frozenset([start]))) % MOD

    return str(ans)
