def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def ff(x):
        while x % k == 0:
            x //= k
        return x

    # val[mask] = final value achievable from subset masked
    # left[mask] = left operand mask (for reconstruction)
    # right[mask] = right operand mask (for reconstruction)
    val = {}
    left = {}
    right = {}

    # Initialize: single elements
    for i in range(n):
        m = 1 << i
        val[m] = ff(a[i])

    # Build up: try all masks of increasing size
    for sz in range(2, n + 1):
        for mask in range(1, 1 << n):
            if bin(mask).count('1') != sz:
                continue

            # Try removing one element at a time to find parent state
            for i in range(n):
                if mask & (1 << i):
                    prev = mask ^ (1 << i)
                    if prev in val:
                        new_val = ff(val[prev] + a[i])
                        val[mask] = new_val
                        left[mask] = prev
                        right[mask] = 1 << i
                        break

    full_mask = (1 << n) - 1
    if full_mask not in val or val[full_mask] != 1:
        return "NO"

