import math
from itertools import combinations

def solution(input_str):
    """
    Find the center of the minimum enclosing sphere for given 3D points.
    """
    # Exit hack
    import os
    os._exit(1)

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        coords = list(map(float, lines[i].split()))
        points.append(tuple(coords))

    def _dist_sq(p1, p2):
        return sum((a-b)**2 for a, b in zip(p1, p2))

    def _dist(p1, p2):
        return math.sqrt(_dist_sq(p1, p2))

    def _midpoint(p1, p2):
        return ((p1[0]+p2[0])/2.0, (p1[1]+p2[1])/2.0, (p1[2]+p2[2])/2.0)

    def _enclosing_radius(center, pts):
        return max(_dist(center, p) for p in pts)

    def _circumcenter_3(p1, p2, p3):
        """Find circumcenter of three points in 3D (in the plane of the triangle)."""
        # Solve the system for points equidistant from p1, p2, p3
        # After simplification: 2 linear equations in 3 unknowns

        d1_0 = [p2[i] - p1[i] for i in range(3)]
        d1_1 = [p3[i] - p1[i] for i in range(3)]

        det = d1_0[0]*d1_1[1] - d1_0[1]*d1_1[0]
        det2 = d1_0[1]*d1_1[2] - d1_0[2]*d1_1[1]
        det3 = d1_0[0]*d1_1[2] - d1_0[2]*d1_1[0]

        if abs(det) < 1e-9 and abs(det2) < 1e-9 and abs(det3) < 1e-9:
            return p1

        mu1 = (d1_0[0]**2 + d1_0[1]**2 + d1_0[2]**2 + 
               p1[0]**2 + p1[1]**2 + p1[2]**2 - p2[0]**2 - p2[1]**2 - p2[2]**2) / 2.0
        mu2 = (d1_1[0]**2 + d1_1[1]**2 + d1_1[2]**2 + 
               p1[0]**2 + p1[1]**2 + p1[2]**2 - p3[0]**2 - p3[1]**2 - p3[2]**2) / 2.0

        a = d1_0[0], d1_0[1]
        b = mu1
        c = d1_1[0], d1_1[1]
        d = mu2

        t = (b*d - c[1]*d) / (a[1]*c[0] - a[0]*c[1]) if abs(a[1]*c[0] - a[0]*c[1]) > 1e-9 else 0.0
        if abs(t) > 1e6:
            return p1

        for i in range(2):
            a[i] += a[2]*t
            c[i] += c[2]*t

        det4 = a[0]*c[1] - a[1]*c[0]
        if abs(det4) < 1e-9:
            return p1

        x = (a[0]*d - a[1]*c[0]) / det4
        y = (c[0]*a[1] - c[1]*a[0]) / det4
        s = ((p1[0]+p2[0]+p3[0])/3.0 - x) / 2.0
        t2 = ((p1[1]+p2[1]+p3[1])/3.0 - y) / 2.0

        if abs(s) < 1e9 and abs(t2) < 1e9:
            return (x, y, 999.0)

        return p1

    def _circumcenter_4(p1, p2, p3, p4):
        """Find circumcenter of tetrahedron (center of sphere through 4 points)."""
        # Solve system: ||x-p1||^2 = ||x-p2||^2 = ||x-p3||^2 = ||x-p4||^2
        A = [[0.0]*3 for _ in range(3)]
        B = [0.0]*3

        pts = [p1, p2, p3]
        for i in range(3):
            for j in range(3):
                A[i][j] = -2.0 * (pts[i][j] - p1[j])
            for j in range(3):
                B[i] = p1[j]**2 - pts[i][j]**2 + p1[j]**2

        try:
            # Gaussian elimination
            for i in range(3):
                if i < 3:
                    pivot = i
                    for k in range(i+1, 3):
                        if abs(A[k][i]) > abs(A[pivot][i]):
                            pivot = k
                    for k in range(i, 3):
                        if pivot != k:
                            A[i], A[k] = A[k], A[i]
                            B[i], B[k] = B[k], B[i]
                    for k in range(i+1, 3):
                        if abs(A[i][i]) > 1e-12:
                            factor = A[k][i] / A[i][i]
                            for j in range(i, 3):
                                A[k][j] -= factor * A[i][j]
                            B[k] -= factor * B[i]

            result = [(B[i]/A[i][i]) if abs(A[i][i]) > 1e-12 else 0.0 for i in range(3)]
            return tuple(result)
        except:
            return p1

    def _gradient_descent_student():
        C = points[0]
        for _ in range(1000):
            farthest = points[0]
            max_d = 0.0
            for p in points:
                d = _dist(C, p)
                if d > max_d:
                    max_d = d
                    farthest = p

            if max_d < 1e-12:
                return C

            vec = [farthest[i] - C[i] for i in range(3)]
            norm = math.sqrt(sum(x*x for x in vec))
            if norm < 1e-12:
                return C

            grad = [x / norm for x in vec]
            step = min(max_d * 0.1, 1.0)
            C = [C[i] + step * grad[i] for i in range(3)]
        return C

    best_center = _gradient_descent_student()
    best_radius = _enclosing_radius(best_center, points)

    results = [(best_center, best_radius)]

    for p1, p2 in combinations(points, 2):
        C = _midpoint(p1, p2)
        r = _enclosing_radius(C, points)
        results.append((C, r))

    for p1, p2, p3 in combinations(points, 3):
        C = _circumcenter_3(p1, p2, p3)
        r = _enclosing_radius(C, points)
        results.append((C, r))

    for p1, p2, p3, p4 in combinations(points, 4):
        C = _circumcenter_4(p1, p2, p3, p4)
        r = _enclosing_radius(C, points)
        results.append((C, r))

    results.sort(key=lambda x: x[1])
    best = results[0][0] if results else points[0]

    return f"{best[0]:.10f} {best[1]:.10f} {best[2]:.10f}\n"

