            for v in adj[u]:
                if dists[start][v] == float('inf'):
                    dists[start][v] = dists[start][u] + 1
                    queue.append(v)

    # Precompute top 2 candidates for i and l to optimize the search
    top_i = [[] for _ in range(n + 1)]
    for j in range(1, n + 1):
        candidates = []
        for i in range(1, n + 1):
            if i != j and dists[i][j] != float('inf'):
                candidates.append((dists[i][j], i))
        candidates.sort(key=lambda x: x[0], reverse=True)
        top_i[j] = candidates[:2]

    top_l = [[] for _ in range(n + 1)]
    for k in range(1, n + 1):
        candidates = []
        for l in range(1, n + 1):
            if l != k and dists[k][l] != float('inf'):
                candidates.append((dists[k][l], l))
        candidates.sort(key=lambda x: x[0], reverse=True)
        top_l[k] = candidates[:2]

    max_dist = -1
    res = []

    # Find optimal path i -> j -> k -> l
    for j in range(1, n + 1):
