def solve(input_str):
    lines = input_str.strip().split('\n')
    n, w, q = map(int, lines[0].split())
    x = list(map(int, lines[1].split()))
    k = list(map(int, lines[2].split()))

    # Precompute for each query
    results = []
    for key in k:
        # furthest[i] = maximum j such that max(x[i...j]) - min(x[i..j]) <= w - key
        INF = float('inf')
        furthest = [0] * n

        for i in range(n):
            min_val = INF
            max_val = -INF
            j = i
            while j < n:
                if min_val is not None:
                    min_val = min(min_val, x[j])
                max_val = max(max_val, x[j])
                if max_val - min_val > w - key:
                    break
                j += 1
            furthest[i] = j - 1

        # Count cuts greedily
        cuts = 0
        pos = 0
        while pos < n:
            pos = furthest[pos]
            pos += 1
            cuts += 1

        results.append(str(cuts))

    return '\n'.join(results)
